  const [loading, setLoading] = useState(true), [modal, setModal] = useState(false), [mobile, setMobile] = useState(false);
  const [dark, setDark] = useState(false), [search, setSearch] = useState(""), [filter, setFilter] = useState("All status");
  const [notice, setNotice] = useState(""), [target, setTarget] = useState(""), [segments, setSegments] = useState<Segment[]>([]), [saving, setSaving] = useState(false);

  const refresh = useCallback(async () => {
    try { const [list, current] = await Promise.all([api<Job[]>("/api/jobs"), api<Usage>("/api/usage")]); setJobs(list); setUsage(current); }
    catch (e) { setNotice((e as Error).message); } finally { setLoading(false); }
  }, []);
  useEffect(() => { void refresh(); const id = window.setInterval(refresh, 4000); return () => window.clearInterval(id); }, [refresh]);
  useEffect(() => { try { setDark(localStorage.getItem("voxora-theme") === "dark"); } catch {} }, []);
  useEffect(() => { document.documentElement.classList.toggle("dark-mode", dark); try { localStorage.setItem("voxora-theme", dark ? "dark" : "light"); } catch {} }, [dark]);
  useEffect(() => {
    if (!selected) { setDetail(null); return; }
    let live = true;
    const fetchDetail = async () => { try { const d = await api<JobDetail>(`/api/jobs/${selected}`); if (live) { setDetail(d); setSegments(d.segments || []); setTarget(d.targets[0] || ""); } } catch (e) { if (live) setNotice((e as Error).message); } };
    void fetchDetail(); const id = window.setInterval(fetchDetail, 2500); return () => { live = false; window.clearInterval(id); };
  }, [selected]);
  const filtered = useMemo(() => jobs.filter(j => (j.name.toLowerCase().includes(search.toLowerCase()) || j.targets.join(" ").toLowerCase().includes(search.toLowerCase())) && (filter === "All status" || j.status === filter)), [jobs, search, filter]);
  const completed = jobs.filter(j => j.status === "Completed").length;
  const submit = async (data: FormData) => { const result = await api<{ id: string }>("/api/jobs", { method: "POST", body: data }); setModal(false); setPage("Dubbing"); setSelected(result.id); await refresh(); };
  const save = async () => { if (!detail) return; setSaving(true); try { await api(`/api/jobs/${detail.id}/segments`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ segments }) }); setNotice("Transcript edits saved."); } catch (e) { setNotice((e as Error).message); } finally { setSaving(false); } };
  const remove = async (id: string) => { if (!window.confirm("Delete this dub and its files?")) return; try { await api(`/api/jobs/${id}`, { method: "DELETE" }); if (selected === id) setSelected(null); await refresh(); } catch (e) { setNotice((e as Error).message); } };
  const navigate = (name: string) => { setSelected(null); setPage(name as Page); };
  const viewJob = (id: string) => { setSelected(id); setPage("Dubbing"); };

  return <div className={`app-shell ${dark ? "dark-mode" : ""}`}>
    <Sidebar active={page} onNavigate={navigate} used={usage.used_minutes} limit={usage.daily_limit_minutes} open={mobile} onClose={() => setMobile(false)} />
    <main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobile(true)} aria-label="Open menu"><Menu size={17}/></button><div className="breadcrumb">Workspace <span>›</span> <strong>{selected ? "Dub details" : page}</strong></div><div className="top-actions"><div className="top-usage"><Clock3 size={14}/><span>{usage.remaining_minutes.toFixed(1)} min left today</span></div><button className="icon-button" onClick={() => setDark(!dark)} aria-label="Toggle theme">{dark ? <Sun size={16}/> : <Moon size={16}/>}</button><button className="primary-button" onClick={() => setModal(true)}><Plus/> New dub</button></div></header>
      <div className="content">
        {selected ? <>{detail ? <DetailView detail={detail} target={target} setTarget={setTarget} segments={segments} setSegments={setSegments} save={save} saving={saving} back={() => setSelected(null)} /> : <div className="empty-state"><LoaderCircle className="spin"/> Loading dub…</div>}</> : page === "Home" || page === "Dubbing" ? <>
          <div className="page-heading"><div><div className="eyebrow">YOUR CREATIVE WORKSPACE</div><h1>{page === "Home" ? "Good work starts with a voice." : "Dubbing projects"}</h1><p>Translate and dub your videos with open-source AI tools.</p></div><button className="primary-button" onClick={() => setModal(true)}><Plus/> Create a dub</button></div>
          <div className="stats-row"><Stat icon={<Film/>} value={String(jobs.length)} label="Total projects"/><Stat icon={<Check/>} value={String(completed)} label="Completed dubs" tone="amber"/><Stat icon={<AudioLines/>} value={`${usage.remaining_minutes.toFixed(1)} min`} label="Free minutes remaining" tone="lavender"/></div>
          <section className="table-card"><div className="table-toolbar"><div><div className="table-title">Recent projects</div><div className="table-subtitle">Your latest dubbing activity</div></div><div className="table-tools"><label className="search-box"><Search size={14}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search projects"/></label><select className="filter-select" value={filter} onChange={e => setFilter(e.target.value)}><option>All status</option>{["Queued","Processing","Completed","Failed"].map(s => <option key={s}>{s}</option>)}</select></div></div>
            <div className="table-scroll"><table className="jobs-table"><thead><tr><th>Project</th><th>Source</th><th>Dubbed into</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody>{filtered.map(job => <tr key={job.id}><td><button className="media-cell row-project" onClick={() => viewJob(job.id)}><span className="thumb">{job.name.match(/\.(mp3|wav|m4a|aac)$/i) ? <FileAudio/> : <Film/>}</span><span>{job.name}<small>{formatTime(job.duration)}</small></span></button></td><td><span className="source-pill">{job.source_language}</span></td><td><div className="language-chips">{job.targets.map(l => <span className="lang-chip" key={l}>{l}</span>)}</div></td><td><span className={`status-badge status-${job.status.toLowerCase()}`}><i className="status-dot"/>{job.status}</span>{job.status === "Processing" && <small className="row-progress">{job.progress}% · {job.step}</small>}</td><td>{dateText(job.created_at)}</td><td><div className="row-actions"><button className="text-button" onClick={() => viewJob(job.id)}>{job.status === "Completed" ? "View" : "Details"}</button><button className="text-button danger" aria-label="Delete project" onClick={() => remove(job.id)}><Trash2 size={14}/></button></div></td></tr>)}</tbody></table>
            {loading ? <div className="empty-state"><LoaderCircle className="spin"/> Loading projects…</div> : filtered.length === 0 ? <div className="empty-state"><div className="empty-orb"><Upload/></div><strong>{jobs.length ? "No matching projects" : "Your studio is ready"}</strong><p>{jobs.length ? "Try another search or filter." : "Create a dub to see your work here."}</p>{!jobs.length && <button className="primary-button" onClick={() => setModal(true)}><Plus/> Start a project</button>}</div> : null}</div>
            <div className="table-footer"><span>Showing {filtered.length} of {jobs.length} projects</span><span>Free &amp; open-source studio</span></div></section>
        </> : <InfoPage page={page} usage={usage} onCreate={() => setModal(true)}/>}
      </div>
    </main>
    {modal && <CreateDub onClose={() => setModal(false)} onSubmit={submit}/>}
    {notice && <div className="toast" role="status">{notice}<button onClick={() => setNotice("")}>×</button></div>}
  </div>;
}

function Stat({ icon, value, label, tone }: {icon: React.ReactNode; value: string; label: string; tone?: string}) { return <div className="stat-card"><div className={`stat-icon ${tone || ""}`}>{icon}</div><div><div className="stat-value">{value}</div><div className="stat-label">{label}</div></div></div>; }
function InfoPage({ page, usage, onCreate }: {page: Page; usage: Usage; onCreate: () => void}) {
 const titles: Record<Page,string> = {Usage:"Your usage",Docs:"Studio guide","Text to Speech":"Text to Speech","Voice Library":"Voice Library","Voice Cloning":"Voice cloning","Speech to Text":"Speech to Text",Home:"Home",Dubbing:"Dubbing"};
 return <><div className="page-heading"><div><div className="eyebrow">VOXORA STUDIO</div><h1>{titles[page]}</h1><p>Free tools for creating and editing accessible audio.</p></div>{page !== "Usage" && page !== "Docs" && <button className="primary-button" onClick={onCreate}><Plus/> New dub</button>}</div>{page === "Usage" ? <div className="content-card info-panel"><div className="stat-icon"><Activity/></div><h2>Daily free minutes</h2><p>{usage.used_minutes.toFixed(1)} of {usage.daily_limit_minutes} minutes used today. Usage resets at midnight local time.</p><div className="usage-track large"><div className="usage-fill" style={{width:`${Math.min(100,usage.used_minutes/usage.daily_limit_minutes*100)}%`}}/></div><strong>{usage.remaining_minutes.toFixed(1)} minutes remaining</strong></div> : page === "Docs" ? <div className="content-card info-panel docs-panel"><h2>How dubbing works</h2><ol><li>Upload audio or video under 2 GB and one hour.</li><li>Select a source language and one or more target languages.</li><li>Voxora transcribes, translates, generates speech, and syncs it to the original timing.</li><li>Review your result and download MP4, MP3, SRT, or VTT files.</li></ol><p>Processing runs locally with FFmpeg and optional open-source AI models. Edge TTS requires an internet connection.</p><button className="primary-button" onClick={onCreate}><Plus/> Create a dub</button></div> : <div className="content-card info-panel"><div className="stat-icon"><FileText/></div><h2>{titles[page]} is coming soon</h2><p>The current MVP focuses on full video and audio dubbing. Use the new dub workflow to get started.</p><button className="primary-button" onClick={onCreate}><Plus/> Start a dub</button></div>}</>;
