function DetailView({detail,target,setTarget,segments,setSegments,save,saving,back}: {detail: JobDetail;target:string;setTarget:(v:string)=>void;segments:Segment[];setSegments:(v:Segment[])=>void;save:()=>void;saving:boolean;back:()=>void}) {
 const done = detail.status === "Completed", files = detail.result?.[target] || {};
 const update = (index:number, value:string) => setSegments(segments.map((s,i) => i === index ? {...s,translation:{...s.translation,[target]:value}} : s));
 return <><button className="back-link" onClick={back}>‹ All projects</button><div className="page-heading detail-heading"><div><div className="eyebrow">{done ? "DUB COMPLETE" : detail.status.toUpperCase()}</div><h1>{detail.name}</h1><p>{detail.message} {detail.duration ? `· ${formatTime(detail.duration)}` : ""}</p></div><span className={`status-badge status-${detail.status.toLowerCase()}`}><i className="status-dot"/>{detail.status}</span></div>
 {!done ? <section className="progress-card"><div className="progress-header"><div><strong>{detail.step}</strong><p>{detail.message}</p></div><div className="progress-number">{detail.progress}%</div></div><div className="progress-track"><span style={{width:`${detail.progress}%`}}/></div>{PIPELINE_STEPS.map((step,i) => {const current=detail.step===step, complete=PIPELINE_STEPS.indexOf(detail.step)>i||done; return <div className="progress-step" key={step}><div className={`step-icon ${complete?"done":current?"current":""}`}>{complete?<Check size={14}/>:current?<LoaderCircle size={14} className="spin"/>:i+1}</div><div><strong>{step}</strong><p>{current?detail.message:complete?"Step complete":"Waiting"}</p></div><span className="step-state">{complete?"Done":current?"In progress":"Pending"}</span></div>})}{detail.status === "Failed" && <div className="error-box">{detail.error || detail.message}</div>}</section> : <><div className="result-toolbar"><label>Dub language <select className="filter-select" value={target} onChange={e=>setTarget(e.target.value)}>{detail.targets.map(t=><option key={t}>{t}</option>)}</select></label><div className="result-actions"><a className="secondary-button" href={mediaUrl(detail.original_url)} target="_blank">Original media</a></div></div><div className="result-layout"><section className="result-card"><div className="card-header"><strong>Dubbed preview</strong><span>{target}</span></div><div className="result-media">{files.mp4 ? <video controls playsInline src={mediaUrl(files.mp4)}/> : <audio controls src={mediaUrl(files.mp3)}/>}</div><div className="download-grid">{([['mp4','Video MP4'],['mp3','Audio MP3'],['srt','Subtitles SRT'],['vtt','Subtitles VTT']] as const).map(([kind,label])=>files[kind]&&<a key={kind} href={mediaUrl(files[kind])} download className="download-item"><FileText size={15}/><span>{label}</span></a>)}</div></section><section className="result-card transcript-card"><div className="card-header"><div><strong>Transcript &amp; translation</strong><small>{segments.length} timed segments</small></div><button className="primary-button small-button" onClick={save} disabled={saving}>{saving?"Saving…":"Save edits"}</button></div><div className="segment-list">{segments.map((s,i)=><div className="segment-row" key={`${s.start}-${i}`}><span className="segment-time">{formatTime(s.start)}</span><div className="segment-text"><p>{s.text}</p><textarea value={s.translation[target] || ""} onChange={e=>update(i,e.target.value)} aria-label={`Translation segment ${i+1}`}/></div></div>)}</div></section></div></>}
 </>;
}

"use client";
import { DragEvent, FormEvent, useRef, useState } from "react";
import { AudioLines, Check, FileAudio, FileVideo, Mic, Plus, Upload, X } from "lucide-react";
import { LANGUAGES } from "../lib/api";

export default function CreateDub({onClose,onSubmit}:{onClose:()=>void;onSubmit:(data:FormData)=>Promise<void>}) {
 const [file,setFile]=useState<File|null>(null),[drag,setDrag]=useState(false),[tab,setTab]=useState<"upload"|"record">("upload");
 const [source,setSource]=useState("Auto-detect"),[targets,setTargets]=useState<string[]>(["Hindi"]),[gender,setGender]=useState("Female"),[speed,setSpeed]=useState("1"),[music,setMusic]=useState(true),[burn,setBurn]=useState(false),[glossary,setGlossary]=useState(""),[clone,setClone]=useState(false),[consent,setConsent]=useState(false),[error,setError]=useState(""),[busy,setBusy]=useState(false),[recording,setRecording]=useState(false);
 const input=useRef<HTMLInputElement>(null),recorder=useRef<MediaRecorder|null>(null),chunks=useRef<Blob[]>([]),stream=useRef<MediaStream|null>(null);
 const accept=(f?:File)=>{if(!f)return;setError("");if(f.size>2*1024*1024*1024){setError("File exceeds the 2 GB upload limit.");return}setFile(f)};
 const drop=(e:DragEvent<HTMLDivElement>)=>{e.preventDefault();setDrag(false);accept(e.dataTransfer.files[0])};
 const toggle=(lang:string)=>setTargets(old=>old.includes(lang)?old.filter(x=>x!==lang):[...old,lang]);
 const record=async()=>{try{if(recording){recorder.current?.stop();stream.current?.getTracks().forEach(t=>t.stop());setRecording(false);return}stream.current=await navigator.mediaDevices.getUserMedia({audio:true});chunks.current=[];const r=new MediaRecorder(stream.current);recorder.current=r;r.ondataavailable=e=>{if(e.data.size)chunks.current.push(e.data)};r.onstop=()=>accept(new File(chunks.current,[`recording-${Date.now()}.webm`],{type:"audio/webm"}));r.start();setRecording(true)}catch{setError("Microphone permission was denied or recording is unavailable.")}};
 const submit=async(e:FormEvent)=>{e.preventDefault();setError("");if(!file){setError("Choose a media file first.");return}if(!targets.length){setError("Select at least one target language.");return}if(clone&&!consent){setError("Confirm you have permission to use this voice.");return}const data=new FormData();data.append("file",file);data.append("source_language",source);data.append("targets",JSON.stringify(targets));data.append("voice_gender",gender);data.append("speech_speed",speed);data.append("keep_music",String(music));data.append("burn_subtitles",String(burn));data.append("glossary",glossary);data.append("cloning",String(clone));data.append("clone_consent",String(consent));setBusy(true);try{await onSubmit(data)}catch(err){setError((err as Error).message)}finally{setBusy(false)}};
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-head"><div><h2 id="modal-title">Create a new dub</h2><p>Turn your media into multilingual content.</p></div><button className="close-button" onClick={onClose} aria-label="Close"><X size={16}/></button></div><form onSubmit={submit}><div className="modal-body"><div className="tab-row"><button type="button" className={`tab ${tab==="upload"?"selected":""}`} onClick={()=>setTab("upload")}>Upload file</button><button type="button" className={`tab ${tab==="record"?"selected":""}`} onClick={()=>setTab("record")}>Record audio</button></div>
 <div className={`drop-zone ${drag?"dragging":""}`} onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={drop}><div className="upload-icon">{file?.type.startsWith("audio")?<FileAudio size={19}/>:file?<FileVideo size={19}/>:tab==="record"?<Mic size={19}/>:<Upload size={19}/>}</div>{file?<><div className="drop-title">{file.name}</div><div className="file-meta">{(file.size/1024/1024).toFixed(1)} MB · Ready to dub <button type="button" className="inline-clear" onClick={()=>setFile(null)}>Remove</button></div></>:<><div className="drop-title">{tab==="upload"?"Drop your media here":"Record a voice sample"}</div><p className="drop-copy">{tab==="upload"?"Video or audio · up to 2 GB and 60 minutes":"Your browser will ask for microphone permission"}</p>{tab==="upload"?<><button type="button" className="file-button" onClick={()=>input.current?.click()}><Plus size={14}/> Browse files</button><input ref={input} hidden type="file" accept="video/*,audio/*,.mkv,.avi,.flac,.ogg" onChange={e=>accept(e.target.files?.[0])}/></>:<button type="button" className={`file-button ${recording?"recording-button":""}`} onClick={record}><Mic size={14}/>{recording?"Stop recording":"Start recording"}</button>}</>}</div>
 <div className="form-grid"><div className="field"><label htmlFor="source">Source language</label><select id="source" value={source} onChange={e=>setSource(e.target.value)}><option>Auto-detect</option>{LANGUAGES.map(l=><option key={l}>{l}</option>)}</select></div><div className="field"><label htmlFor="voice">Generated voice</label><select id="voice" value={gender} onChange={e=>setGender(e.target.value)}><option>Female</option><option>Male</option></select></div><div className="field span-two"><span className="field-label">Dub into <small>Select one or more</small></span><div className="target-grid">{LANGUAGES.map(l=><button type="button" key={l} className={`target-option ${targets.includes(l)?"selected":""}`} onClick={()=>toggle(l)}>{targets.includes(l)&&<Check size={12}/>} {l}</button>)}</div></div><div className="field"><label htmlFor="speed">Speech speed</label><select id="speed" value={speed} onChange={e=>setSpeed(e.target.value)}><option value="0.85">0.85× slower</option><option value="1">1× natural</option><option value="1.1">1.1×</option><option value="1.2">1.2× faster</option></select></div><div className="field"><label htmlFor="glossary">Glossary <small>(optional)</small></label><input id="glossary" value={glossary} onChange={e=>setGlossary(e.target.value)} placeholder="Names, brands, comma-separated"/></div></div>
 <div className="option-list"><label className="check-option"><input type="checkbox" checked={music} onChange={e=>setMusic(e.target.checked)}/><span><strong>Preserve background music</strong><small>Separate speech from the original soundtrack with Demucs.</small></span></label><label className="check-option"><input type="checkbox" checked={burn} onChange={e=>setBurn(e.target.checked)}/><span><strong>Burn subtitles into video</strong><small>Also receive downloadable SRT and VTT files.</small></span></label><details className="advanced-toggle"><summary>Voice cloning rights &amp; consent</summary><div className="clone-content"><label className="check-option"><input type="checkbox" checked={clone} onChange={e=>setClone(e.target.checked)}/><span><strong>Enable voice cloning</strong><small>Cloning is not implemented in this MVP; standard generated voices will be used.</small></span></label>{clone&&<label className="consent-line"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> I own this voice or have explicit permission to use it.</label>}</div></details></div>{error&&<div className="error-box" role="alert">{error}</div>}</div><div className="modal-actions"><span>Free plan · daily minutes apply</span><button className="primary-button" type="submit" disabled={busy}>{busy?"Uploading…":<><AudioLines size={16}/> Create dub</>}</button></div></form></section></div>;
}

