@media (max-width:420px) { .stats-row { grid-template-columns:1fr 1fr; }.stat-card:last-child { display:none; }.form-grid,.advanced-content { grid-template-columns:1fr; }.span-two { grid-column:auto; }.top-usage { display:none; }.page-heading { gap:8px; }.page-heading .primary-button { gap:5px; }.page-heading .primary-button svg { width:14px; }.table-footer { padding:11px 12px; }.download-grid { grid-template-columns:repeat(2,1fr); } }

