.table-footer { display:flex;justify-content:space-between;padding:12px 18px;color:#a1aaa6;font-size:10px;border-top:1px solid #f0f2f1; }
.danger { color:#b97070; }.inline-clear { border:0;background:transparent;color:#b56b6b;font-size:10px;margin-left:8px;text-decoration:underline; }
.field small { color:#a0aaa5;font-size:9px;font-weight:500; }.field input[type=checkbox],.check-option input,.consent-line input { accent-color:#239b68; }
.option-list { display:flex;flex-direction:column;gap:8px;margin-top:16px; }.check-option { display:flex;align-items:flex-start;gap:9px;color:#56635c;font-size:11px;cursor:pointer; }.check-option input { margin-top:2px; }.check-option strong,.check-option small { display:block; }.check-option small { color:#9aa49f;font-size:9px;margin-top:3px;line-height:1.45; }.advanced-toggle { border:1px solid #edf1ee;border-radius:8px;padding:10px 12px;color:#637169;font-size:10px; }.advanced-toggle summary { cursor:pointer;font-weight:700; }.clone-content { padding-top:12px; }.consent-line { display:flex;align-items:center;gap:7px;margin:12px 0 0 23px;font-size:10px;color:#78837c; }
