13: export async function api<T>(path: string, init?: RequestInit): Promise<T> {
14:   const response = await fetch(`${API_URL}${path}`, { ...init, credentials: "include" });
15:   if (!response.ok) {
16:     let message = `Request failed (${response.status})`;
17:     try { const data = await response.json(); message = data.detail || data.message || message; } catch { /* use status message */ }
